const emailValid = value => /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(String(value || '').trim());
const chatValid = value => /^-?[1-9]\d*$/.test(String(value || '').trim());
const escapeHtml = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const httpUrl = value => { const text = String(value || '').trim(); const match = text.match(/^https?:\/\/([^\s/<>"'?#]+)(?:[/?#][^\s<>"']*)?$/i); return match && !match[1].includes('@') ? text : ''; };
const outputError = (name, recipient, telegram = false) => {
  try {
    const result = $(name).item.json;
    if (!result || result.error) return String(result?.error?.message || result?.error || 'Không có kết quả gửi.');
    if (telegram) return result.ok === true || Number.isInteger(result.message_id) ? '' : 'Telegram chưa xác nhận gửi thành công.';
    if (Array.isArray(result.rejected) && result.rejected.length) return 'Máy chủ email từ chối người nhận.';
    if (Array.isArray(result.accepted)) return result.accepted.some(email => String(email).toLowerCase() === String(recipient).toLowerCase()) ? '' : 'Máy chủ email chưa chấp nhận người nhận.';
    return result.messageId ? '' : 'Máy chủ email chưa xác nhận gửi thành công.';
  } catch { return 'Kênh chưa chạy hoặc không trả kết quả.'; }
};
const deliveryStatus = flags => flags.every(Boolean) ? 'SENT' : flags.some(Boolean) ? 'PARTIAL' : 'FAILED';

return (function reviewPhase() {
  const validated = (function configValidation() {
  const item = $json;
  if (!httpUrl(item.apiBaseUrl)) throw Error('Địa chỉ backend không hợp lệ.');
  if (!String(item.automationSecret || '').trim()) throw Error('Thiếu khóa xác thực tự động hóa.');
  if (!emailValid(item.senderEmail)) throw Error('Email gửi không hợp lệ.');
  return [{ json: { ...item, apiBaseUrl: item.apiBaseUrl.replace(/\/+$/, ''), senderEmail: item.senderEmail.trim(), telegramReady: chatValid(item.telegramChatId) } }];
})();
  const config = validated[0].json;
  if (!httpUrl(config.reviewFormUrl)) throw Error('Đường dẫn thực hiện đánh giá không hợp lệ.');
  return [{ json: { ...config, ...(function manualScheduleOptions() {
  const manual = $execution.mode === 'test';
  const date = manual ? String($json.manualRunDate || '').trim() : '';
  if (date) {
    const parsed = new Date(date + 'T00:00:00Z');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(parsed.getTime()) || parsed.toISOString().slice(0,10) !== date || Number(date.slice(0,4)) < 2000 || Number(date.slice(0,4)) > 2100) throw Error('Ngày chạy thủ công phải là ngày hợp lệ dạng YYYY-MM-DD (2000–2100).');
  }
  return { allowRepeat: manual, asOf: date ? date + 'T08:00:00+07:00' : '' };
})(), runId: String($execution.id) } }];
})();

const response = $input.first().json;
const payload = response.data ?? response;
const reminders = Array.isArray(payload.reminders) ? payload.reminders : [];
const config = $('Prepare Review Request').first().json;
